func headerDeclarationKind(kind string) option.Option[HeaderDeclarationKind] {
	switch kind {
	case "record":
		return option.Some[HeaderDeclarationKind]{Value: HeaderRecord{}}
	case "macro-object":
		return option.Some[HeaderDeclarationKind]{Value: HeaderObjectMacro{}}
	case "macro-function":
		return option.Some[HeaderDeclarationKind]{Value: HeaderFunctionMacro{}}
	case "type":
		return option.Some[HeaderDeclarationKind]{Value: HeaderType{}}
	case "opaque":
		return option.Some[HeaderDeclarationKind]{Value: HeaderOpaque{}}
	default:
		return option.None[HeaderDeclarationKind]{}
	}
}
